extra_head_css:
.compare-layout { display: flex; gap: 20px; flex-wrap: wrap; }
    .compare-sidebar { flex: 0 0 280px; display: flex; flex-direction: column; gap: 14px; }
    .compare-main { flex: 1; min-width: 300px; }
    @media (max-width: 768px) { .compare-layout { flex-direction: column; } .compare-sidebar { flex: none; width: 100%; } }

    .mode-btns { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 6px; }
    .mode-btn {
      padding: 8px 4px; border: 1px solid var(--border-color); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-secondary); cursor: pointer;
      font-size: .75rem; text-align: center; transition: all .2s;
    }
    .mode-btn:hover { border-color: var(--accent); color: var(--text-primary); }
    .mode-btn.active { border-color: var(--accent); background: rgba(99,102,241,.1); color: var(--accent); }

    .upload-pair { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
    .upload-half {
      border: 2px dashed var(--border-color); border-radius: 12px;
      padding: 20px; text-align: center; cursor: pointer; transition: all .2s;
      background: var(--bg-secondary);
    }
    .upload-half:hover { border-color: var(--accent); background: var(--bg-tertiary); }
    .upload-half.loaded { border-color: var(--success); background: rgba(34,197,94,.08); }
    .upload-half .upload-icon { font-size: 1.8rem; margin-bottom: 6px; }
    .upload-half .upload-label { font-size: .8rem; color: var(--text-secondary); }
    .upload-half input[type="file"] { display: none; }

    .compare-preview {
      background: var(--bg-secondary); border: 1px solid var(--border-color); border-radius: 12px;
      padding: 16px; display: flex; align-items: center; justify-content: center;
      min-height: 400px; position: relative; overflow: hidden; user-select: none;
    }

    /* Slider mode */
    .slider-container { position: relative; display: inline-block; max-width: 100%; }
    .slider-img-bottom, .slider-img-top {
      display: block; max-width: 100%; max-height: 65vh; border-radius: 4px;
    }
    .slider-img-top {
      position: absolute; top: 0; left: 0;
      clip-path: inset(0 50% 0 0); transition: clip-path 0.05s;
    }
    .slider-handle {
      position: absolute; top: 0; bottom: 0; left: 50%; width: 4px;
      background: var(--accent); cursor: ew-resize; z-index: 10;
      transform: translateX(-50%);
    }
    .slider-handle::before {
      content: '⟷⟶'; position: absolute; top: 50%; left: 50%;
      transform: translate(-50%, -50%); background: var(--accent); color: white;
      border-radius: 20px; padding: 4px 8px; font-size: .7rem;
      white-space: nowrap; box-shadow: 0 2px 8px rgba(0,0,0,.3);
    }

    /* Side-by-side mode */
    .sidebyside-container { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; }
    .sidebyside-container img { max-width: 48%; max-height: 60vh; border-radius: 8px; }

    /* Overlay mode */
    .overlay-container { position: relative; display: inline-block; }
    .overlay-bottom, .overlay-top {
      display: block; max-width: 100%; max-height: 65vh; border-radius: 4px;
    }
    .overlay-top {
      position: absolute; top: 0; left: 0; opacity: 0.5;
      mix-blend-mode: normal;
    }
    .overlay-slider { width: 100%; margin-top: 8px; accent-color: var(--accent); }

    .info-row { display: flex; gap: 12px; font-size: .8rem; color: var(--text-secondary); padding: 8px 12px; background: var(--bg-secondary); border-radius: 8px; margin-top: 12px; flex-wrap: wrap; }
    .info-row span { display: flex; align-items: center; gap: 4px; }
